// ---- Broadcast / announcements (admin -> customer portal) -------------------
model Announcement {
  id        String                    @id @default(cuid())
  title     String
  body      String?
  level     String                    @default("INFO") // INFO | SUCCESS | WARNING | CRITICAL
  active    Boolean                   @default(true)
  expiresAt DateTime? // optional auto-hide
  createdBy String? // admin user id (audit only)
  createdAt DateTime                  @default(now())
  dismissals AnnouncementDismissal[]
}

// One row per (announcement, user) that dismissed it. userId is a plain scalar
// (no relation) so this is self-contained and doesn't touch the frozen User model.
model AnnouncementDismissal {
  id             String       @id @default(cuid())
  announcementId String
  announcement   Announcement @relation(fields: [announcementId], references: [id], onDelete: Cascade)
  userId         String
  createdAt      DateTime     @default(now())

  @@unique([announcementId, userId])
  @@index([userId])
}

