"use client";

import { useState } from "react";
import { dismissAnnouncement, type AnnouncementView } from "@/lib/actions-broadcast";

const TONE: Record<string, string> = {
  INFO: "border-brand-500/30 bg-brand-500/[0.08] text-brand-100",
  SUCCESS: "border-emerald-500/30 bg-emerald-500/[0.08] text-emerald-100",
  WARNING: "border-amber-500/30 bg-amber-500/[0.08] text-amber-100",
  CRITICAL: "border-red-500/30 bg-red-500/[0.08] text-red-100",
};

/** Dismissible admin broadcasts, shown at the top of the customer portal. Each
 *  dismissal is persisted per-user (server-side), so it stays gone across pages
 *  and devices. Optimistic: it disappears immediately, then records the dismissal. */
export function AnnouncementBanner({ announcements }: { announcements: AnnouncementView[] }) {
  const [hidden, setHidden] = useState<Set<string>>(new Set());
  const visible = announcements.filter((a) => !hidden.has(a.id));
  if (visible.length === 0) return null;

  return (
    <div className="mb-4 space-y-2">
      {visible.map((a) => (
        <div key={a.id} className={`flex items-start justify-between gap-3 rounded-xl border px-4 py-3 text-sm ${TONE[a.level] ?? TONE.INFO}`}>
          <div className="min-w-0">
            <p className="font-semibold">{a.title}</p>
            {a.body && <p className="mt-0.5 whitespace-pre-wrap text-[13px] opacity-90">{a.body}</p>}
          </div>
          <button
            aria-label="Dismiss"
            className="shrink-0 rounded p-1 opacity-70 transition-opacity hover:opacity-100"
            onClick={() => {
              setHidden((prev) => new Set(prev).add(a.id));
              void dismissAnnouncement(a.id);
            }}
          >
            ✕
          </button>
        </div>
      ))}
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { createAnnouncement, toggleAnnouncement, deleteAnnouncement } from "@/lib/actions-broadcast";

type Row = {
  id: string;
  title: string;
  body: string | null;
  level: string;
  active: boolean;
  expiresAt: Date | null;
  createdAt: Date;
  _count: { dismissals: number };
};

const LEVELS = ["INFO", "SUCCESS", "WARNING", "CRITICAL"];
const DOT: Record<string, string> = { INFO: "bg-brand-400", SUCCESS: "bg-emerald-400", WARNING: "bg-amber-400", CRITICAL: "bg-red-400" };

export function BroadcastAdmin({ rows }: { rows: Row[] }) {
  const router = useRouter();
  const [title, setTitle] = useState("");
  const [body, setBody] = useState("");
  const [level, setLevel] = useState("INFO");
  const [expiresAt, setExpiresAt] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");

  async function post() {
    setErr("");
    setBusy(true);
    const res = await createAnnouncement({ title, body, level, expiresAt: expiresAt || null });
    setBusy(false);
    if (res.error) { setErr(res.error); return; }
    setTitle(""); setBody(""); setLevel("INFO"); setExpiresAt("");
    router.refresh();
  }

  return (
    <div className="space-y-6">
      <div className="card space-y-3">
        <p className="text-sm font-semibold text-white">New broadcast</p>
        <input className="input" placeholder="Title (shown to every customer)" value={title} onChange={(e) => setTitle(e.target.value)} maxLength={200} />
        <textarea className="input" rows={3} placeholder="Optional detail…" value={body} onChange={(e) => setBody(e.target.value)} maxLength={2000} />
        <div className="flex flex-wrap items-center gap-3 text-sm">
          <label className="flex items-center gap-1.5 text-slate-400">Level
            <select className="input py-1 text-xs" value={level} onChange={(e) => setLevel(e.target.value)}>
              {LEVELS.map((l) => <option key={l} value={l}>{l.toLowerCase()}</option>)}
            </select>
          </label>
          <label className="flex items-center gap-1.5 text-slate-400">Auto-hide after (optional)
            <input type="datetime-local" className="input py-1 text-xs" value={expiresAt} onChange={(e) => setExpiresAt(e.target.value)} />
          </label>
          <button className="btn-primary ml-auto" onClick={post} disabled={busy || !title.trim()}>{busy ? "Posting…" : "Broadcast to all customers"}</button>
        </div>
        {err && <p className="text-sm text-red-400">{err}</p>}
      </div>

      <div className="card p-0">
        <div className="border-b border-white/[0.06] px-4 py-3 text-sm font-semibold text-white">Broadcasts</div>
        {rows.length === 0 ? (
          <p className="px-4 py-6 text-sm text-slate-400">No broadcasts yet.</p>
        ) : (
          <ul className="divide-y divide-white/[0.06]">
            {rows.map((r) => (
              <li key={r.id} className="flex items-start justify-between gap-3 px-4 py-3">
                <div className="min-w-0">
                  <p className="flex items-center gap-2 text-sm font-medium text-slate-100">
                    <span className={`h-2 w-2 rounded-full ${DOT[r.level] ?? DOT.INFO}`} />
                    {r.title}
                    {!r.active && <span className="rounded bg-white/10 px-1.5 py-0.5 text-[10px] text-slate-400">paused</span>}
                  </p>
                  {r.body && <p className="mt-0.5 truncate text-xs text-slate-500">{r.body}</p>}
                  <p className="mt-1 text-[11px] text-slate-500">
                    {new Date(r.createdAt).toLocaleDateString()} · dismissed by {r._count.dismissals}
                    {r.expiresAt ? ` · hides ${new Date(r.expiresAt).toLocaleString()}` : ""}
                  </p>
                </div>
                <div className="flex shrink-0 gap-3 text-xs">
                  <button className="text-slate-300 hover:underline" onClick={async () => { await toggleAnnouncement(r.id); router.refresh(); }}>{r.active ? "Pause" : "Resume"}</button>
                  <button className="text-red-400 hover:underline" onClick={async () => { if (confirm("Delete this broadcast?")) { await deleteAnnouncement(r.id); router.refresh(); } }}>Delete</button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

